UPDATE TRAVEL_PACKAGE
SET package_status = 'PENDING',
    reject_reason = NULL
WHERE package_idx = #{packageIdx}
  AND seller_user_idx = #{sellerUserIdx}
  AND package_status IN ('DRAFT', 'REJECTED')

UPDATE TRAVEL_PACKAGE
SET booking_count = COALESCE(booking_count, 0) + 1
WHERE package_idx = #{packageIdx}

UPDATE TRAVEL_PACKAGE_BOOKING
SET booking_status = 'CANCELLED',
    cancelled_at = NOW(),
    cancel_reason = #{cancelReason}
WHERE package_booking_idx = #{packageBookingIdx}
  AND user_idx = #{userIdx}
  AND booking_status = 'BOOKED'

UPDATE TRAVEL_PACKAGE
SET booking_count = GREATEST(COALESCE(booking_count, 0) - 1, 0)
WHERE package_idx = #{packageIdx}

