SELECT tpr.package_revision_idx, tpr.package_idx, tpr.seller_user_idx, tpr.package_title, tpr.package_summary, tpr.package_content, tpr.package_price, tpr.currency_code, tpr.start_date, tpr.end_date, tpr.min_people, tpr.max_people, tpr.main_image_path, tpr.revision_status, tpr.reject_reason, tpr.requested_at, tpr.reviewed_by_user_idx, tpr.reviewed_at, tp.package_title AS current_package_title, st.name AS spot_name, st.region AS spot_region, u.nickname AS seller_nickname FROM TRAVEL_PACKAGE_REVISION tpr JOIN TRAVEL_PACKAGE tp ON tp.package_idx = tpr.package_idx JOIN SPOT_TRAVEL st ON st.spot_idx = tp.spot_idx JOIN USERS u ON u.user_idx = tpr.seller_user_idx WHERE 1 = 1
AND tpr.revision_status = #{status}
ORDER BY CASE tpr.revision_status WHEN 'PENDING' THEN 1 WHEN 'REJECTED' THEN 2 WHEN 'APPROVED' THEN 3 ELSE 4 END, tpr.requested_at DESC, tpr.package_revision_idx DESC
